// #0532cb מסך גורמים מקצועיים קבועים — вкладка «גורמים מקצועיים קבועים» в «פרופיל החברה» (/onboarding компании с пройденным мастером), роль ADMIN.
// Кейсы: .qa/tests/onboarding-professionals/OPR-05..OPR-09. План: specs/onboarding-professionals.md.
// ВАЖНО: профиль сохраняется ОДНИМ объектом (баг #318805, last-write-wins) — тесты @data идут строго по одному
// (проект `data`, workers 1; здесь ещё и serial) и не должны идти параллельно с другими тестами, пишущими профиль.
// Тестовые данные — QA-AUTO-…; afterEach удаляет все оставшиеся QA-AUTO- специалистов (категория без людей исчезает сама).
import { test, expect, Page } from '@playwright/test';
import { authState, qaName } from '../helpers/tenderflow';

const BANNER = 'גורם קבוע לא צריך משתמש במערכת: מקבל קישור מאובטח, מעלה או חותם על המסמך, והמסמך חוזר ישירות לתיק.';
const ADD_CATEGORY = 'הוסף גורם מקצועי נוסף';
const ADD_CATEGORY_HINT = 'למשל: מהנדס חתום, יועץ בטיחות, ממונה אבטחת מידע, מודד מוסמך';
const REMOVE_TITLE = 'הסרת גורם מקצועי';

const tabPanel = (page: Page) => page.getByRole('tabpanel');
const moreButton = (page: Page, name: string) => page.getByRole('button', { name: `פעולות נוספות: ${name}` });
const removeDialog = (page: Page) => page.getByRole('dialog', { name: REMOVE_TITLE });

async function openProfessionalsTab(page: Page) {
  await page.goto('/onboarding');
  await page.getByRole('tab', { name: /גורמים מקצועיים קבועים/ }).click();
  await expect(page.getByRole('tab', { name: /גורמים מקצועיים קבועים/ })).toHaveAttribute('aria-selected', 'true');
  await expect(tabPanel(page).getByText(BANNER)).toBeVisible();
  await expect(page.getByRole('region', { name: 'מורשה חתימה' })).toBeVisible();
}

/** Добавить специалиста inline в блок типа (שם מלא / אימייל / טלפון) и дождаться строки в списке. */
async function addInline(page: Page, region: ReturnType<Page['getByRole']>, name: string, phone = '0501234567', email = `qa.auto+${Date.now()}@example.com`) {
  const form = region.getByRole('form', { name: 'הוספת גורם מקצועי' });
  await form.getByRole('textbox', { name: 'שם מלא' }).fill(name);
  await form.getByRole('textbox', { name: 'אימייל' }).fill(email);
  await form.getByRole('textbox', { name: 'טלפון' }).fill(phone);
  await form.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(region.getByRole('listitem').filter({ hasText: name })).toHaveCount(1);
  return email;
}

/** «•••» → «הסרה» → подтверждение в окне. */
async function removePerson(page: Page, name: string) {
  await moreButton(page, name).click();
  await page.getByRole('menuitem', { name: 'הסרה' }).click();
  await removeDialog(page).getByRole('button', { name: 'הסרה', exact: true }).click();
  await expect(removeDialog(page)).toHaveCount(0);
  await expect(page.getByText(name, { exact: true })).toHaveCount(0);
}

async function removeQaAutoPeople(page: Page) {
  await openProfessionalsTab(page);
  const leftovers = page.getByRole('button', { name: /^פעולות נוספות: QA-AUTO-/ });
  while (await leftovers.count()) {
    const label = (await leftovers.first().getAttribute('aria-label')) ?? '';
    await removePerson(page, label.replace('פעולות נוספות: ', ''));
  }
}

test.describe('פרופיל החברה — גורמים מקצועיים קבועים (קריאה בלבד)', () => {
  test.use({ storageState: authState('admin') });

  test('באנר הלשונית — הנוסח המאושר בלבד #0532cb @desktop @prod-safe', async ({ page }) => {
    await openProfessionalsTab(page);
    // Figma 1137:2544 дословно; старый текст (Р4) не должен остаться
    await expect(tabPanel(page).getByText(BANNER, { exact: true })).toBeVisible();
    await expect(page.getByText('רושמים פעם אחת את פרטי הקשר')).toHaveCount(0);
    // три типа сразу видны
    for (const type of ['עורך דין', 'רואה חשבון', 'מורשה חתימה']) {
      await expect(page.getByRole('region', { name: type })).toBeVisible();
    }
  });

  test('בלוק "הוסף גורם מקצועי נוסף" והטקסט למשל #0532cb @desktop @prod-safe', async ({ page }) => {
    await openProfessionalsTab(page);
    await expect(tabPanel(page).getByRole('button', { name: ADD_CATEGORY, exact: true })).toBeVisible();
    await expect(tabPanel(page).getByText(ADD_CATEGORY_HINT, { exact: true })).toBeVisible();
  });

  test('שם קטגוריה ריק או רווחים בלבד נדחה בהודעה, בלי שמירה #0532cb @desktop @prod-safe', async ({ page }) => {
    await openProfessionalsTab(page);
    const regionsBefore = await page.getByRole('region').count();
    await page.getByRole('button', { name: ADD_CATEGORY, exact: true }).click();
    const input = page.getByRole('textbox', { name: 'שם הקטגוריה' });
    const add = page.getByRole('button', { name: 'הוספה', exact: true });

    await add.click();
    await expect(page.getByText('יש להזין שם קטגוריה')).toBeVisible();

    await input.fill('   ');
    await add.click();
    await expect(page.getByText('יש להזין שם קטגוריה')).toBeVisible();
    await expect(page.getByRole('region')).toHaveCount(regionsBefore);

    await page.getByRole('button', { name: 'ביטול', exact: true }).click();
    await expect(input).toHaveCount(0);
  });

  test('שם קטגוריה "עורך דין" מצטרף לסוג הקיים ולא יוצר כרטיס חדש #0532cb @desktop @prod-safe', async ({ page }) => {
    await openProfessionalsTab(page);
    const regionsBefore = await page.getByRole('region').count();
    await page.getByRole('button', { name: ADD_CATEGORY, exact: true }).click();
    await page.getByRole('textbox', { name: 'שם הקטגוריה' }).fill('עורך דין');
    await page.getByRole('button', { name: 'הוספה', exact: true }).click();

    // тот же блок «עורך דין»: появилась форма добавления внутри него, нового региона нет
    await expect(page.getByRole('region', { name: 'עורך דין' })).toHaveCount(1);
    await expect(page.getByRole('region', { name: 'עורך דין' }).getByRole('form', { name: 'הוספת גורם מקצועי' })).toBeVisible();
    await expect(page.getByRole('region')).toHaveCount(regionsBefore);
    // ничего не сохраняем: уходим со страницы с неотправленной формой
  });

  test('בנייד 390 האימייל מוצג במלואו בלי גלילה אופקית #0532cb @mobile', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await openProfessionalsTab(page);
    const email = page.getByText('qa-lawyer@example.com', { exact: false }).first();
    await expect(email).toBeVisible();
    const fit = await email.evaluate((el) => {
      const r = el.getBoundingClientRect();
      return {
        clipped: el.scrollWidth > el.clientWidth + 1,
        inside: r.left >= 0 && r.right <= window.innerWidth,
        pageScroll: document.documentElement.scrollWidth > window.innerWidth + 1,
      };
    });
    expect(fit.clipped, 'email обрезан').toBe(false);
    expect(fit.inside, 'email выходит за экран').toBe(true);
    expect(fit.pageScroll, 'горизонтальная прокрутка страницы').toBe(false);
  });
});

test.describe('פרופיל החברה — גורמים מקצועיים קבועים (שינוי נתונים)', () => {
  test.describe.configure({ mode: 'serial' });
  test.use({ storageState: authState('admin') });
  test.afterEach(async ({ page }) => {
    await removeQaAutoPeople(page);
  });

  test('שם קטגוריה חופשי יוצר כרטיס חדש עם שם, טלפון ואימייל ונשמר #0532cb @desktop @data', async ({ page }) => {
    await openProfessionalsTab(page);
    const category = qaName('cat');
    const person = qaName('pro');

    await page.getByRole('button', { name: ADD_CATEGORY, exact: true }).click();
    await page.getByRole('textbox', { name: 'שם הקטגוריה' }).fill(category);
    await page.getByRole('button', { name: 'הוספה', exact: true }).click();

    const region = page.getByRole('region', { name: category });
    await expect(region).toBeVisible();
    const form = region.getByRole('form', { name: 'הוספת גורם מקצועי' });
    for (const field of ['שם מלא', 'טלפון', 'אימייל']) await expect(form.getByRole('textbox', { name: field })).toBeVisible();

    const email = await addInline(page, region, person);
    await expect(region.getByRole('listitem').filter({ hasText: person })).toContainText(email);

    // сохранено в профиль: после перезагрузки карточка категории и человек на месте
    await openProfessionalsTab(page);
    await expect(page.getByRole('region', { name: category }).getByRole('listitem').filter({ hasText: person })).toHaveCount(1);
  });

  test('הסרה: "חזרה" ו-Esc לא מוחקים, אישור מוחק ונשאר מחוק אחרי רענון #0532cb @desktop @data', async ({ page }) => {
    await openProfessionalsTab(page);
    const person = qaName('pro');
    const region = page.getByRole('region', { name: 'מורשה חתימה' });
    await region.getByRole('button', { name: 'הוסף מורשה חתימה' }).click();
    await addInline(page, region, person);
    const row = region.getByRole('listitem').filter({ hasText: person });

    // «•••» → «הסרה» открывает окно «הסרת גורם מקצועי» с именем
    await moreButton(page, person).click();
    await page.getByRole('menuitem', { name: 'הסרה' }).click();
    await expect(removeDialog(page)).toBeVisible();
    await expect(removeDialog(page)).toContainText(person);

    // «חזרה» не удаляет
    await removeDialog(page).getByRole('button', { name: 'חזרה', exact: true }).click();
    await expect(removeDialog(page)).toHaveCount(0);
    await expect(row).toHaveCount(1);

    // Esc не удаляет
    await moreButton(page, person).click();
    await page.getByRole('menuitem', { name: 'הסרה' }).click();
    await expect(removeDialog(page)).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(removeDialog(page)).toHaveCount(0);
    await expect(row).toHaveCount(1);

    // после перезагрузки всё ещё на месте
    await openProfessionalsTab(page);
    await expect(row).toHaveCount(1);

    // подтверждение удаляет, и после перезагрузки его нет
    await removePerson(page, person);
    await expect(row).toHaveCount(0);
    await openProfessionalsTab(page);
    await expect(page.getByText(person, { exact: true })).toHaveCount(0);
  });
});
